package org.sleepwell.app;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.view.inspector.WindowInspector;import android.widget.TextView;
import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.UiDevice;import org.junit.Test;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;
/** Real settings actions/private persistence only; no model, microphone, alarm, permissions or cue output. */
public final class AlarmDefaultsFlowTest {
 final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);AlarmDefaultsActivity activity;String step="admission";
 final List<Activity> owned=new CopyOnWriteArrayList<>();

 interface Task {void run(Fixture f)throws Exception;}
 final class Fixture implements AlarmDefaultsSettings.Port {
  final String name="alarm-defaults-ui-"+UUID.randomUUID();final SharedPreferences prefs=c.getSharedPreferences(name,Context.MODE_PRIVATE);final AtomicInteger saves=new AtomicInteger(),opens=new AtomicInteger();volatile boolean fail;volatile CountDownLatch block=new CountDownLatch(0);final CountDownLatch entered=new CountDownLatch(1);
  public AlarmDefaultsSettings.Read read(){return AlarmDefaultsSettings.read(prefs);}
  public void save(AlarmDefaults value){assertNotEquals(Looper.getMainLooper(),Looper.myLooper());entered.countDown();try{if(!block.await(30,TimeUnit.SECONDS))throw new IllegalStateException("Fixture save was not released");}catch(InterruptedException e){throw new IllegalStateException(e);}if(fail)throw new IllegalStateException("Synthetic settings storage error");AlarmDefaultsSettings.of(prefs).save(value);saves.incrementAndGet();}
 }
 void fixture(Task task)throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",d.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(TrackingService.running);assertFalse(AlarmService.active);assertFalse(Prefs.flag(c,"ringing"));assertFalse(Prefs.flag(c,"tracking"));Map<String,?> before=new HashMap<>(Prefs.of(c).getAll());AlarmDefaultsSettings.Factory old=AlarmDefaultsSettings.factory;Records.Factory oldRecords=Records.factory;Fixture f=new Fixture();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle saved){owned.add(a);assertTrue("Only the explicit defaults screen may open",a instanceof AlarmDefaultsActivity);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle saved){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(callbacks);
  try{i.runOnMainSync(()->{AlarmDefaultsSettings.factory=ctx->{f.opens.incrementAndGet();return f;};Records.factory=ctx->{throw new AssertionError("Saving alarm defaults cannot open recordings");};});task.run(f);assertEquals(before,Prefs.of(c).getAll());}
  catch(Exception|AssertionError error){try{File dir=folder();d.takeScreenshot(new File(dir,"alarm-defaults-failure.png"));d.dumpWindowHierarchy(new File(dir,"alarm-defaults-failure.xml"));try(PrintWriter out=new PrintWriter(new File(dir,"alarm-defaults-failure.txt"),"UTF-8")){out.println(step);out.println(f.prefs.getAll());error.printStackTrace(out);}}catch(Exception failure){error.addSuppressed(failure);}throw error;}
  finally{f.block.countDown();try{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});await(()->owned.stream().allMatch(Activity::isDestroyed));for(Activity a:owned)assertTrue(((AlarmDefaultsActivity)a).awaitWorkers(8000));}finally{app.unregisterActivityLifecycleCallbacks(callbacks);i.runOnMainSync(()->{AlarmDefaultsSettings.factory=old;Records.factory=oldRecords;});try{assertTrue(f.prefs.edit().clear().commit());}finally{assertTrue(c.deleteSharedPreferences(f.name));assertEquals(before,Prefs.of(c).getAll());}}}
 }
 void await(java.util.function.BooleanSupplier condition)throws Exception{long end=SystemClock.elapsedRealtime()+8000;while(!condition.getAsBoolean()&&SystemClock.elapsedRealtime()<end)Thread.sleep(20);assertTrue(step,condition.getAsBoolean());}
 View find(View root,String label){if(label.contentEquals(root.getContentDescription()==null?"":root.getContentDescription())||root instanceof TextView&&label.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View view=find(group.getChildAt(n),label);if(view!=null)return view;}return null;}
 View focused(){View found=null;for(View root:WindowInspector.getGlobalWindowViews())if(root.hasWindowFocus()&&root.isAttachedToWindow()&&root.isLaidOut()&&root.getContext().getPackageName().equals(c.getPackageName())){assertNull("One focused app window",found);found=root;}return found;}
 boolean shown(String value){boolean[] yes={false};i.runOnMainSync(()->yes[0]=activity!=null&&!activity.isDestroyed()&&find(activity.getWindow().getDecorView(),value)!=null);return yes[0];}
 void ready()throws Exception{await(()->{boolean[] yes={false};i.runOnMainSync(()->yes[0]=activity!=null&&!activity.isDestroyed()&&activity.hasWindowFocus()&&focused()==activity.getWindow().getDecorView());return yes[0];});}
 String template(){Alarm draft=new Alarm(91);draft.hour=22;draft.enabled=true;draft.days.add(3);draft.volume=42;draft.tone="chime";draft.snoozeMinutes=9;return AlarmDefaultsJson.encode(new AlarmDefaults(draft));}
 void launch()throws Exception{step="launch settings";Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmDefaultsActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,AlarmDefaultsActivity.class).putExtra("template",template()).putExtra("visualReview",true).putExtra("verificationLabel","Private settings fixture · no audio").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(AlarmDefaultsActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}ready();}
 void recreate()throws Exception{step="recreate settings";AlarmDefaultsActivity old=activity;Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmDefaultsActivity.class.getName(),null,false);try{i.runOnMainSync(old::recreate);activity=(AlarmDefaultsActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}await(old::isDestroyed);ready();}
 void reopen()throws Exception{AlarmDefaultsActivity old=activity;i.runOnMainSync(old::finish);await(old::isDestroyed);assertTrue(old.awaitWorkers(8000));launch();}
 Rect measured(View root,String label){View view=find(root,label);assertNotNull(label,view);while(!view.isClickable()&&view.getParent() instanceof View)view=(View)view.getParent();assertTrue(label+" enabled",view.isEnabled()&&view.isClickable());Rect shown=new Rect();assertTrue(label,view.getGlobalVisibleRect(shown));assertEquals(label+" whole width",view.getWidth(),shown.width());assertEquals(label+" whole height",view.getHeight(),shown.height());assertTrue(label+"48dp width",shown.width()>=Design.dp(c,48));assertTrue(label+"48dp height",shown.height()>=Design.dp(c,48));int[] pos=new int[2];view.getLocationOnScreen(pos);return new Rect(pos[0],pos[1],pos[0]+view.getWidth(),pos[1]+view.getHeight());}
 void frame(View root)throws Exception{CountDownLatch rendered=new CountDownLatch(1);i.runOnMainSync(()->{assertSame(root,focused());root.getViewTreeObserver().registerFrameCommitCallback(rendered::countDown);root.invalidate();});assertTrue(rendered.await(5,TimeUnit.SECONDS));i.runOnMainSync(()->assertSame(root,focused()));}
 void input(View root,String label)throws Exception{step="single input "+label;await(()->{boolean[] yes={false};i.runOnMainSync(()->{if(focused()!=root)return;View view=find(root,label);if(view==null)return;while(!view.isClickable()&&view.getParent() instanceof View)view=(View)view.getParent();if(!view.isEnabled()||!view.isClickable())return;view.requestRectangleOnScreen(new Rect(0,0,view.getWidth(),view.getHeight()),true);Rect visible=new Rect();yes[0]=view.getGlobalVisibleRect(visible)&&visible.width()==view.getWidth()&&visible.height()==view.getHeight();});return yes[0];});frame(root);Rect[] bounds={null};i.runOnMainSync(()->bounds[0]=measured(root,label));assertTrue("One owned native input",d.click(bounds[0].centerX(),bounds[0].centerY()));}
 void click(String label)throws Exception{ready();input(activity.getWindow().getDecorView(),label);}
 View dialog(String title)throws Exception{View[] root={null};await(()->{i.runOnMainSync(()->{View candidate=focused();if(candidate!=null&&candidate!=activity.getWindow().getDecorView()&&find(candidate,title)!=null)root[0]=candidate;});return root[0]!=null;});return root[0];}
 void choose(String title,String value)throws Exception{View root=dialog(title);input(root,value);await(()->!root.isAttachedToWindow());ready();}
 File folder(){File dir=new File(c.getExternalFilesDir(null),"verification");assertTrue(dir.isDirectory()||dir.mkdirs());return dir;}
 void capture(String name)throws Exception{step="capture "+name;ready();View root=activity.getWindow().getDecorView();frame(root);i.runOnMainSync(()->{View save=find(root,"Saving…");if(save==null)save=find(root,"Save new alarm defaults");assertNotNull(save);Rect bounds=new Rect();assertTrue(save.getGlobalVisibleRect(bounds));assertEquals("Entire fixed Save action",save.getHeight(),bounds.height());assertTrue(save.getHeight()>=Design.dp(c,48));});assertTrue(d.takeScreenshot(new File(folder(),"alarm-defaults-"+name+".png")));}
 @Test public void explicitSaveRecreateReopenAndResetOnlyAffectFutureAlarmBehavior()throws Exception{fixture(f->{launch();assertTrue(f.prefs.getAll().isEmpty());capture("initial");recreate();capture("recreated");assertTrue(f.prefs.getAll().isEmpty());click("Save new alarm defaults");await(()->shown("Saved for new alarms."));assertEquals(1,f.saves.get());Alarm next=AlarmDefaultsSettings.load(c).create(105);assertEquals(42,next.volume);assertEquals("chime",next.tone);assertEquals(9,next.snoozeMinutes);assertEquals(7,next.hour);assertFalse(next.enabled);assertTrue(next.days.isEmpty());capture("saved");reopen();assertEquals(42,f.read().create(106).volume);capture("reopened");click("Restore factory defaults");await(()->shown("Factory defaults restored."));assertEquals(2,f.saves.get());assertEquals(85,f.read().create(107).volume);capture("reset");});}
 @Test public void heldSaveAndFailureSurviveRecreationWithOneExplicitRetry()throws Exception{fixture(f->{launch();f.block=new CountDownLatch(1);f.fail=true;click("Save new alarm defaults");assertTrue(f.entered.await(5,TimeUnit.SECONDS));await(()->shown("Saving…"));capture("saving");recreate();await(()->shown("Saving…"));i.runOnMainSync(()->{assertFalse(find(activity.getWindow().getDecorView(),"Saving…").isEnabled());assertFalse(find(activity.getWindow().getDecorView(),"Restore factory defaults").isEnabled());});capture("saving-recreated");f.block.countDown();await(()->shown("Defaults could not be saved. Try again."));assertTrue(f.prefs.getAll().isEmpty());capture("save-error");f.fail=false;click("Save new alarm defaults");await(()->shown("Saved for new alarms."));assertEquals(1,f.saves.get());assertEquals(42,f.read().create(99).volume);capture("retry");});}
}
